const incoming = $json || {};
const body = (incoming.body && typeof incoming.body === 'object' && !Array.isArray(incoming.body)) ? incoming.body : {};
const root = { ...incoming, ...body };

let skus = root.skus || root.sku || [];
if (typeof skus === 'string') {
  skus = skus.split(/[\n,;]+/).map(s => s.trim()).filter(Boolean);
}
if (!Array.isArray(skus)) skus = [skus];
skus = skus.map(s => String(s).trim().replace(/'/g, '')).filter(Boolean);

const clientId = String(root.client_id || '').trim();
let oiRaw = String(root.oi || '').trim();
if (!oiRaw && /^support:(\d+)/i.test(clientId)) {
  oiRaw = clientId.replace(/^support:/i, '');
}
const digits = oiRaw.replace(/\D/g, '');
const oi = digits ? `${digits}.` : '';
const oiSql = digits ? `'${digits}.'` : '';

const skusInClause = skus.length ? skus.map(s => `'${s}'`).join(', ') : "''";
const skipQuery = skus.length > 0 && !oiSql;

return [{
  json: {
    skus,
    skusInClause,
    oi,
    oiSql,
    client_id: clientId,
    platform: String(root.platform || '').trim(),
    skipQuery,
    success: skipQuery ? false : true,
    error: skipQuery ? 'OI ausente. Selecione a conta AnyMarket (OI) antes de consultar SKUs.' : ''
  }
}];

const prep = $('Preparar SKUs1').first().json;
return [{
  json: {
    success: false,
    error: prep.error || 'OI ausente. Selecione a conta AnyMarket antes de consultar SKUs.',
    oi: prep.oi || '',
    sku_map: {},
    count: 0
  }
}];

const prep = $('Preparar SKUs1').first().json;
const rows = $input.all().map(item => item.json);

const sku_map = {};
for (const s of prep.skus || []) {
  sku_map[s] = { cat: [], trad: [], id_product: '', sku_id: '' };
}

for (const row of rows) {
  if (!row || !row.sku) continue;

  const sku = String(row.sku).trim();
  const mlb = String(row.mlb || '').trim().toUpperCase();
  const isCatalog = Number(row.is_catalog || 0);
  const status = String(row.status_in_marketplace || '').trim();
  const idProduct = String(row.id_product || '').trim();
  const skuId = String(row.sku_id || '').trim();

  if (!sku_map[sku]) {
    sku_map[sku] = { cat: [], trad: [], id_product: '', sku_id: '' };
  }
  if (idProduct && !sku_map[sku].id_product) sku_map[sku].id_product = idProduct;
  if (skuId && !sku_map[sku].sku_id) sku_map[sku].sku_id = skuId;

  if (mlb.startsWith('MLB')) {
    const anuncio = { mlb, status };
    if (isCatalog === 1) sku_map[sku].cat.push(anuncio);
    else sku_map[sku].trad.push(anuncio);
  }
}

return [{
  json: {
    success: true,
    oi: prep.oi || '',
    sku_map,
    count: Object.keys(sku_map).length
  }
}];
